export const money=n=>new Intl.NumberFormat('de-CH',{style:'currency',currency:'CHF'}).format(n/100);
export const itemName=k=>ITEMS[k]?.[0]||k;
export const capacity=s=>40+((s.inventory.backpack||0)>0?40:0);
export const storageCapacity=s=>20+((s.inventory.chest||s.storage.chest||0)>0?80:0);
export const weight=s=>Object.values(s.inventory).reduce((a,b)=>a+b,0);
export const sellPrice=k=>['hay','grain','bucket','water'].includes(k)?0:Math.floor(ITEMS[k][2]*.45);
const fail=message=>({ok:false,message});
function commit(state,next,message){Object.assign(state,next);return{ok:true,message};}
function transact(state,{take={},give={},cost=0,earn=0,energy=0,stats={},reason=null,ref=null}){
 if(!Number.isSafeInteger(cost)||!Number.isSafeInteger(earn)||cost<0||earn<0||!Number.isFinite(energy)||energy<0)return fail('Ungültige Aktion.');
 if(state.coins<cost)return fail('Es fehlen '+money(cost-state.coins)+'.');
 if(state.energy<energy)return fail('Es fehlen '+Math.ceil(energy-state.energy)+' Energie. Raste in der Hütte.');
 const inventory={...state.inventory};
 for(const[k,n]of Object.entries(take)){if(!ITEMS[k]||!Number.isSafeInteger(n)||n<1)return fail('Ungültige Menge.');if((inventory[k]||0)<n)return fail('Es fehlen '+(n-(inventory[k]||0))+' × '+itemName(k)+'.');inventory[k]-=n;if(!inventory[k])delete inventory[k];}
 for(const[k,n]of Object.entries(give)){if(!ITEMS[k]||!Number.isSafeInteger(n)||n<1)return fail('Ungültiger Gegenstand.');inventory[k]=(inventory[k]||0)+n;}
 const next={...state,inventory};if(weight(next)>capacity(next))return fail('Der Rucksack ist voll. Verbrauche Nahrung, verkaufe Funde oder lagere Gegenstände in der Hütte.');
 const coins=state.coins-cost+earn;if(!Number.isSafeInteger(coins)||coins>1000000000)return fail('Der Geldbetrag ist zu gross.');
 const changes={...state.stats};for(const[k,n]of Object.entries(stats))changes[k]=(changes[k]||0)+n;
 return{ok:true,next:{inventory,coins,energy:state.energy-energy,stats:changes,ledger:cost||earn?[...state.ledger,{day:state.day,delta:earn-cost,reason,ref}].slice(-60):state.ledger}};
}
export function craft(state,id,station){const r=RECIPES.find(r=>r.id===id);if(!r)return fail('Unbekanntes Rezept.');if(station!==r.station)return fail('Benötigter Ort: '+STATIONS[r.station]+' in der Alphütte.');const t=transact(state,{take:r.ingredients,give:r.output,energy:r.energy,stats:{crafts:1}});return t.ok?commit(state,t.next,r.name+' hergestellt.'):t;}
export function resourceReady(state,node){const last=state.gathered[node.id];return !last||state.day-last>=(node.respawnDays||1);}
export function takeAlpAxe(state){if(state.activities.discoveries.includes('alp-axe'))return fail('Das Beil hast du bereits erhalten. Ersatz gibt es an der Werkbank oder im Dorfladen.');const r=exchangeInventory(state,{give:{axe:1}});if(r.ok)state.activities.discoveries.push('alp-axe');return r.ok?{ok:true,message:'Dein Beil liegt jetzt im Rucksack. Markierte Nutzbäume liefern Holz und wachsen nach drei Nächten nach.'}:r;}
export function collect(state,node){if(!resourceReady(state,node))return fail(node.tree?'Der Nutzbaum wächst nach. Noch '+(node.respawnDays-(state.day-state.gathered[node.id]))+' Nächte.':'Heute bereits gesammelt. Nach einer Nacht erscheint hier wieder Nachschub.');if(node.tool&&!(state.inventory[node.tool]>0))return fail('Du brauchst: '+itemName(node.tool)+'.');const amount=node.amount*(node.item==='wood'&&!node.tree&&state.inventory.axe?2:1);const t=transact(state,{give:{[node.item]:amount},energy:node.energy,stats:{gathers:1}});if(!t.ok)return t;return commit(state,{...t.next,gathered:{...state.gathered,[node.id]:state.day}},'+'+amount+' × '+itemName(node.item)+(node.tree?' · Nutzbaum gefällt; Nachwuchs in drei Nächten.':''));}
export function consume(state,id){const value=ITEMS[id]?.[3];if(!value)return fail('Dieser Gegenstand ist nicht essbar.');if(state.energy>=100&&(!state.survival||(id==='water'?state.survival.thirst:state.survival.hunger)>=100))return fail('Deine Energie ist bereits voll.');const t=transact(state,{take:{[id]:1}});if(!t.ok)return t;if(state.survival){if(id==='water')state.survival.thirst=Math.min(100,state.survival.thirst+40);else state.survival.hunger=Math.min(100,state.survival.hunger+value*.8);}return commit(state,{...t.next,energy:Math.min(100,state.energy+value)},itemName(id)+' genossen · +'+Math.min(value,100-state.energy)+' Energie.');}
export function trade(state,id,mode,atShop){if(!atShop)return fail('Handel ist im Dorfladen möglich.');if(!ITEMS[id]||!['buy','sell'].includes(mode))return fail('Ungültiger Handel.');if(mode==='sell'&&id==='caveCheese')return fail('Deinen Höhlenkäse kauft der Portmann-Store in der Stadt an.');if(mode==='sell'&&['fishingRod','sickle','hay','grain','bucket','water'].includes(id))return fail('Kostenlose Grundversorgung und Wasser werden nicht angekauft.');if(mode==='buy'&&!SHOP.includes(id))return fail('Dieser Gegenstand wird hier nicht angeboten.');const t=mode==='buy'?transact(state,{cost:ITEMS[id][2],give:{[id]:1},stats:{spent:ITEMS[id][2]},reason:'buy',ref:id}):transact(state,{take:{[id]:1},earn:sellPrice(id),stats:{earned:sellPrice(id),sales:1},reason:'sell',ref:id});return t.ok?commit(state,t.next,itemName(id)+(mode==='buy'?' gekauft.':' verkauft.')):t;}
export function claimQuest(state,id){const q=QUESTS.find(q=>q.id===id);if(!q||!q.goal(state))return fail('Diese Aufgabe ist noch nicht abgeschlossen.');if(state.claimed.includes(id))return fail('Die Belohnung wurde bereits abgeholt.');const t=transact(state,{earn:q.reward,stats:{earned:q.reward},reason:'quest',ref:id});return t.ok?commit(state,{...t.next,claimed:[...state.claimed,id]},q.name+' · +'+money(q.reward)):t;}
export function rest(state,sleep,inside){if(!inside)return fail('In der Alphütte kannst du kostenlos rasten und schlafen.');if(sleep&&state.day>=100000)return fail('Die maximale Anzahl Spieltage wurde erreicht.');state.energy=Math.min(100,state.energy+(sleep?100:(state.inventory.stool?40:25)));state.stamina=100;if(sleep){state.day++;if(state.environment)state.environment.minute=480;advanceFarm(state);if(state.alpLife?.housed)for(const id of Object.keys(state.alpLife.housed))state.alpLife.housed[id]=true;}return{ok:true,message:sleep?'Guten Morgen! Tag '+state.day+' beginnt. Die Tiere sind im Stall; du kannst sie wieder auf die Weide lassen.':'Gut erholt · Energie aufgefüllt.'};}
export function transfer(state,id,toChest,inside){if(!inside)return fail('Die Lagertruhe steht in der Alphütte.');const from=toChest?state.inventory:state.storage;if(!ITEMS[id]||!(from[id]>0))return fail('Der Gegenstand ist nicht vorhanden.');const inv={...state.inventory},storage={...state.storage},a=toChest?inv:storage,b=toChest?storage:inv;a[id]--;if(!a[id])delete a[id];b[id]=(b[id]||0)+1;if(weight({...state,inventory:inv})>capacity({...state,inventory:inv}))return fail('Der Rucksack hat nicht genug Platz.');if(Object.values(storage).reduce((a,b)=>a+b,0)>storageCapacity({...state,inventory:inv,storage}))return fail('Deine Lagertruhe ist voll. Eine selbst hergestellte Lagertruhe erweitert sie auf 100 Plätze.');state.inventory=inv;state.storage=storage;return{ok:true,message:itemName(id)+(toChest?' eingelagert.':' eingepackt.')};}
export function tickVitals(state,dt,running){if(state.survival){state.survival.hunger=Math.max(0,state.survival.hunger-dt*.013);state.survival.thirst=Math.max(0,state.survival.thirst-dt*(running?.055:.025));if(state.survival.hunger===0||state.survival.thirst===0)state.energy=Math.max(0,state.energy-dt*.035);}if(running){state.stamina=Math.max(0,state.stamina-12*dt);state.energy=Math.max(0,state.energy-(state.inventory.boots?.12:.16)*dt);}else state.stamina=Math.min(100,state.stamina+9*dt);}

export function exchangeInventory(state,action){const t=transact(state,action);return t.ok?commit(state,t.next,'Vorräte aktualisiert.'):t;}
